// Everything this execution needs: the pb's own execution id goes to the
// TheHive custom field and the writeback (sub-workflows have their own ids).
const input = $input.first().json;
if (!input.config || !input.config.writeback) throw new Error(`${$workflow.name} needs the lib-config output as \`config\``);
return [{ json: {
  alert: input.alert,
  config: input.config,
  context: { playbook: $workflow.name, n8n_execution_id: $execution.id, recv_execution_id: input.recv_execution_id ?? null },
  // From lib-route-alert (N8N-1.3); null when called without a route.
  route: input.route ?? null,
} }];

// Actions taken, as written to TheHive (lib-thehive-writeback): lib-alert-base's
// sections (route, TheHive alert, warninglists, enrichment), then the SSH
// correlation, the response proposal (C9 v0) and this playbook's "Systems
// changed" line.
const c = $('Context').first().json;
const b = $('Alert base (lib-alert-base)').first().json;
const u = b.upsert;
// repair: the alert existed without a writeback and this run completed it (N8N-1.4).
const repair = b.outcome === 'repaired';
const actions = [...b.writeback.sections];
// SSH correlation (N8N-4.2): related alerts from the same source address, this
// alert's campaign tag, the escalation of itself or of the related brute-force
// alerts, and the recommended response. Failures are reported, never parked.
const esc = $('Escalation result').isExecuted ? $('Escalation result').first().json : null;
function writeLine(t) {
  if (!t) return null;
  if (t.skipped) return t.skipped;
  if (!t.patch.ok) return `update failed (${t.patch.class}${t.patch.attempts ? ` after ${t.patch.attempts} call(s)` : ''})`;
  return null;
}
function commentLine(t) {
  if (!t.comment) return t.patch.ok ? 'escalation comment not written' : 'escalation comment not attempted';
  if (!t.comment.ok) return `escalation comment failed (${t.comment.class}${t.comment.attempts ? ` after ${t.comment.attempts} call(s)` : ''})`;
  return t.comment.written ? 'escalation comment written' : 'escalation comment already there';
}
function correlationLines(u) {
  if (!$('Correlate (lib-ssh-correlate)').isExecuted) {
    return [u.duplicate && !repair ? 'SSH correlation: not run (duplicate: done when the alert was created).' : 'SSH correlation: not run.'];
  }
  const cr = $('Correlate (lib-ssh-correlate)').first().json;
  // On Error = continue: an unexpected failure inside the lib arrives as {error}.
  if (typeof cr.status !== 'string') return [`SSH correlation: failed (unexpected error in lib-ssh-correlate: ${cr.error ?? 'no result'}); alert unaffected.`];
  if (cr.status === 'skipped') return [`SSH correlation: skipped (${cr.reason}).`];
  const sc = c.config.ssh_correlation;
  const span = cr.window_s % 3600 === 0 ? `${cr.window_s / 3600} h` : `${cr.window_s} s`;
  const iso = (ms) => new Date(ms).toISOString();
  const lines = [];
  if (cr.status === 'failed') {
    lines.push(`SSH correlation (same source within ${span}): failed (${cr.class}${cr.attempts ? ` after ${cr.attempts} call(s)` : ''}); related alerts not looked at, nothing escalated.`);
  } else {
    const shown = cr.listed.length < cr.related_total ? `; the ${cr.listed.length} nearest in time shown` : '';
    const cut = cr.truncated ? `; the query's limit (${sc.query_limit}) was reached, so more may exist` : '';
    lines.push(`Related (same source within ${span}): ${cr.related_total} alert(s) from ${cr.srcip} (case templates ${sc.templates.join(', ')}; ${cr.window_s} s either side of this alert's event time)${shown}${cut}.`);
    for (const r of cr.listed) {
      lines.push(`  Wazuh ${r.wazuh_alert_id}: rule ${r.rule_id ?? 'unknown'} at ${r.date_iso} (TheHive ${r.thehive_alert_id}, ${r.case_template}, severity ${r.severity})`);
    }
  }
  const self = esc?.self ?? null;
  const campaign = `${sc.tags.campaign_prefix}${cr.srcip}`;
  if (cr.plan?.self) {
    const fail = writeLine(self);
    lines.push(cr.plan.self.add_tags.includes(campaign)
      ? (fail ? `Tag ${campaign} not written: ${fail}.` : `Tagged this alert ${campaign}.`)
      : `Already tagged ${campaign}.`);
  }
  if (self?.escalation) {
    const e = self.escalation;
    const fail = writeLine(self);
    lines.push(`Escalated this alert (${sc.tags.escalated}): rule ${e.by_rule_id} alert ${e.marker_alert_id} (TheHive ${e.by_thehive_alert_id}, at ${iso(e.by_date_ms)}) shows a successful login from ${cr.srcip}; `
      + (fail ? `${fail}.` : `${self.severity_to !== null ? `severity ${self.severity_from} → ${self.severity_to}` : `severity unchanged (${self.severity_from})`}, ${commentLine(self)}.`));
  }
  if (cr.role === 'login' && cr.status === 'done') {
    const rel = esc?.related ?? [];
    lines.push(rel.length === 0
      ? `Escalation (${sc.tags.escalated}): no related ${sc.bruteforce_template} alert to escalate.`
      : `Escalation (${sc.tags.escalated}) of ${rel.length} related ${sc.bruteforce_template} alert(s):`);
    for (const t of rel) {
      const fail = writeLine(t);
      lines.push(`  Escalated: TheHive ${t.thehive_alert_id} (Wazuh ${t.wazuh_alert_id}, rule ${t.rule_id ?? 'unknown'} at ${iso(t.date_ms)}): `
        + (fail ? `${fail}.` : `severity ${t.severity_from} → ${t.severity_final}${t.severity_to === null ? ' (unchanged)' : ''}, `
          + `${t.add_tags.length > 0 ? `tagged ${t.add_tags.join(', ')}` : 'tag already there'}, ${commentLine(t)}; `
          + `${t.metrics_result ? `asox-metrics severity: ${t.metrics_result.line}` : 'asox-metrics not updated'}.`));
    }
  }
  return lines;
}
// C9 v0: the proposal an analyst approves with response.approval.tag
// (pb-ssh-response), and its marker line `<proposal marker> <agent id>
// <srcip> <command> <timeout>`, which pb-ssh-response reads back from this
// comment (the comment's time is the proposal's). No proposal: the
// recommendation, with the reason.
function responseLines() {
  if (!$('Proposal input').isExecuted) return [];
  const pi = $('Proposal input').first().json;
  const resp = c.config.response;
  const rec = (why) => `Recommended: block ${pi.srcip ?? 'the source address'} (response actions, C9); nothing was changed (no proposal: ${why}).`;
  if (!pi.propose) return [rec(pi.reason)];
  // On Error = continue: an unexpected failure inside the lib arrives as {error}.
  const r = $('Proposal (lib-wazuh-active-response)').first().json;
  if (typeof r.status !== 'string') return [rec(`unexpected error in lib-wazuh-active-response: ${r.error ?? 'no result'}`)];
  if (r.status !== 'proposed') return [rec(r.reason ?? r.line)];
  const w = resp.approval.window_s;
  const span = w % 3600 === 0 ? `${w / 3600} h` : `${w} s`;
  return [
    `Proposed: ${r.command} ${r.srcip} on ${r.agent.name} for ${r.timeout_s} s (${r.mode}). Approve by adding the tag ${resp.approval.tag} to this alert within ${span}.`,
    `${resp.markers.proposal} ${r.agent.id} ${r.srcip} ${r.command} ${r.timeout_s}`,
  ];
}
actions.push(...correlationLines(u));
actions.push(...responseLines());
actions.push('Systems changed: TheHive (this alert, and the related alerts it escalates), and the Wazuh indexer (asox-metrics documents, C11).');
// C11 (N8N-2.9): lib-alert-base's document plan, with the final severity when
// this run's own escalation raised it (N8N-4.2) and that update succeeded.
const m = b.writeback.metrics;
const metrics = m.mode === 'create' && esc?.self?.patch?.ok && esc.self.severity_to !== null
  ? { ...m, fields: { ...m.fields, severity: esc.self.severity_to } } : m;
return [{ json: {
  thehive_alert_id: b.thehive_alert_id, wazuh_alert_id: b.wazuh_alert_id,
  config: c.config, context: c.context, actions, metrics,
} }];

const b = $('Alert base (lib-alert-base)').first().json;
const r = $('Writeback (lib-thehive-writeback)').first().json;
return [{ json: {
  // repaired: duplicate whose earlier run stopped before its writeback (N8N-1.4).
  outcome: b.outcome,
  after_retry: b.upsert.after_retry === true, // duplicate found by a retried create (N8N-6.2)
  wazuh_alert_id: b.wazuh_alert_id,
  thehive_alert_id: b.thehive_alert_id,
  // N8N-2.4: counts, `not run (duplicate)` or `failed` (unexpected; never parks).
  enrichment: b.enrichment_summary,
  writeback: r.ok ? (r.written ? 'written' : 'already written') : 'failed (parked by lib-error)',
  // C11 (N8N-2.9): metrics: ok | skipped (<why>) | failed (<class>).
  metrics: r.metrics ?? null,
  // N8N-4.2 follow-up: this alert's document re-synced to TheHive's severity
  // after the writeback (the comment is already posted, so only here). null
  // when not run (duplicate, or no document written).
  metrics_resync: (() => {
    if (!$('Severity re-sync plan').isExecuted) return null;
    const p = $('Severity re-sync plan').first().json;
    if (p.status === 'failed') return p.line;
    if (p.status === 'unchanged') return `metrics: severity unchanged (${p.to})`;
    const m = $('Re-sync (lib-metrics-upsert)').first().json;
    if (m.ok === true && !m.skipped) return `metrics: severity re-synced ${p.from} -> ${p.to}`;
    return `metrics: severity re-sync ${p.from} -> ${p.to} failed (${m.skipped ? `skipped: ${m.skipped}` : (m.class ?? 'unexpected')})`;
  })(),
  // N8N-4.2: done / skipped / failed, the related alerts found and the alerts
  // escalated (this one included); `not run` on a duplicate.
  correlation: (() => {
    if (!$('Correlate (lib-ssh-correlate)').isExecuted) return 'not run';
    const cr = $('Correlate (lib-ssh-correlate)').first().json;
    if (typeof cr.status !== 'string') return 'failed (unexpected)';
    const esc = $('Escalation result').isExecuted ? $('Escalation result').first().json : null;
    const escalated = [...(esc?.self?.escalation ? [esc.self] : []), ...(esc?.related ?? [])]
      .filter((t) => t.patch?.ok).map((t) => t.thehive_alert_id);
    return { status: cr.status, reason: cr.reason ?? cr.class ?? null, srcip: cr.srcip, related: cr.related_total ?? 0, escalated };
  })(),
  // C9 v0: the response proposal (`proposed: ...`, `refused (<code>): ...`,
  // `not_sent: ...`, `not proposed: <why>`); null when not looked at (duplicate).
  response_proposal: (() => {
    if (!$('Proposal input').isExecuted) return null;
    const pi = $('Proposal input').first().json;
    if (!pi.propose) return `not proposed: ${pi.reason}`;
    const r = $('Proposal (lib-wazuh-active-response)').first().json;
    return typeof r.line === 'string' ? r.line : `failed (unexpected: ${r.error ?? 'no result'})`;
  })(),
  playbook: $workflow.name,
  route_id: $('Context').first().json.route?.route_id ?? null,
} }];

// lib-alert-base parked the alert (normalize or upsert handed it to lib-error).
const b = $input.first().json;
return [{ json: {
  outcome: 'parked',
  wazuh_alert_id: b.wazuh_alert_id,
  error: b.error,
  message: b.message,
  playbook: $workflow.name,
  route_id: $('Context').first().json.route?.route_id ?? null,
} }];

// lib-config: THEHIVE_ENABLED=false (no cases node on this machine). Recorded,
// not parked: there is nothing to retry.
const b = $input.first().json;
return [{ json: {
  outcome: 'skipped',
  status: b.status,
  wazuh_alert_id: b.wazuh_alert_id,
  playbook: $workflow.name,
  route_id: $('Context').first().json.route?.route_id ?? null,
} }];

// N8N-4.2: related alerts from the same source address (lib-ssh-correlate,
// read-only, one bounded TheHive query). After the enrichment, so an alert
// processed in parallel by the other queue slot has had the most time to
// appear in TheHive. Created or repaired alerts only (a duplicate with its
// writeback was correlated when it was created).
const c = $('Context').first().json;
const b = $('Alert base (lib-alert-base)').first().json;
const u = b.upsert;
return [{ json: {
  canonical: b.canonical,
  thehive_alert_id: u.thehive_alert_id, severity: u.severity, tags: u.tags, source: u.source,
  route: c.route, observables: b.observables, config: c.config,
} }];

// N8N-4.2: the TheHive writes of the correlation, one item per TheHive alert
// (this alert first): tags added (never removed), severity raised (never
// lowered, D12), the escalation comment, and for related alerts their
// asox-metrics severity (lib-metrics-upsert, mode update). Nothing to write
// (correlation skipped, failed unexpectedly, or every tag already there) ->
// one `nothing_to_write` item.
const cr = $('Correlate (lib-ssh-correlate)').first().json;
const c = $('Context').first().json;
const canonical = $('Alert base (lib-alert-base)').first().json.canonical;
const plan = cr && typeof cr.status === 'string' ? cr.plan : null;
const items = [];
if (plan) {
  const s = plan.self;
  const escalation = s.escalation
    ? { marker_alert_id: s.escalation.by_wazuh_alert_id, by_thehive_alert_id: s.escalation.by_thehive_alert_id,
      by_rule_id: s.escalation.by_rule_id, by_date_ms: s.escalation.by_date_ms }
    : null;
  if (s.add_tags.length > 0 || s.severity_to !== null || escalation) {
    items.push({ role: 'self', thehive_alert_id: s.thehive_alert_id, wazuh_alert_id: s.wazuh_alert_id, rule_id: s.rule_id,
      add_tags: s.add_tags, severity_from: s.severity_from, severity_to: s.severity_to,
      severity_final: s.severity_to ?? s.severity_from,
      // This alert's own document is written by its writeback, after this
      // loop, with the final severity (Writeback input); no update here.
      metrics: null, escalation });
  }
  for (const t of plan.targets) {
    items.push({ role: 'related', thehive_alert_id: t.thehive_alert_id, wazuh_alert_id: t.wazuh_alert_id, rule_id: t.rule_id,
      date_ms: t.date_ms, add_tags: t.add_tags, severity_from: t.severity_from, severity_to: t.severity_to,
      severity_final: t.severity_final,
      metrics: { mode: 'update', alert_id: t.wazuh_alert_id, source: t.source, fields: { severity: t.severity_final } },
      escalation: { marker_alert_id: canonical.wazuh_alert_id, by_thehive_alert_id: s.thehive_alert_id,
        by_rule_id: canonical.rule.id, by_date_ms: canonical.date_ms } });
  }
}
if (items.length === 0) return [{ json: { nothing_to_write: true } }];
return items.map((t) => ({ json: { t: { ...t,
  patch_body: { ...(t.add_tags.length > 0 ? { addTags: t.add_tags } : {}), ...(t.severity_to !== null ? { severity: t.severity_to } : {}) },
  srcip: cr.srcip, campaign_tag: `${c.config.ssh_correlation.tags.campaign_prefix}${cr.srcip}` } } }));

// One TheHive alert at a time. Circuit breaker: once a TheHive call failed
// after all its retries (unreachable or 5xx), the remaining alerts are not
// attempted, so an outage costs one alert's retries, not one per related
// alert (the queue row's running_timeout_s stays safe). Earlier alerts: one
// run of "Target result" each (asking for a run past the last one throws).
function earlierTargets() {
  const out = [];
  if (!$('Target result').isExecuted) return out;
  for (let r = 0; r < 1000; r++) {
    let items;
    try { items = $('Target result').all(0, r); } catch (err) { break; }
    out.push(...items.map((it) => it.json.t));
  }
  return out;
}
const t = $input.first().json.t;
const down = earlierTargets().find((x) => x && x.unreachable === true);
if (down) {
  return [{ json: { t: { ...t, skipped: `not attempted: TheHive failed after its retries on ${down.thehive_alert_id}` }, next: 'skip' } }];
}
return [{ json: { t, next: Object.keys(t.patch_body).length > 0 ? 'patch' : 'no_patch' } }];

// The call's attempt number travels with the item (this loop runs the HTTP
// node once per call for every alert, so $runIndex can't count one alert's
// attempts): 1 from the gate, +1 after each "Wait before retry".
const j = $input.first().json;
return [{ json: { t: j.t, attempt: j.retry_of === 'Update TheHive alert' ? j.attempt + 1 : 1 } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. The attempt
// number comes with the call ("Call: Update TheHive alert", same run index: one run per call),
// not from $runIndex. Never parks: the last failure goes into the writeback.
const r = $input.first().json;
const call = $('Call: Update TheHive alert').all(0, $runIndex)[0].json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Update TheHive alert';
const attempt = call.attempt;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { ...call, decision: 'retry', retry_of: NODE, stage: NODE, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { ...call, decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...call, decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// Result of the alert update (tags added, severity raised), or nothing to
// update (every tag already there, severity already high enough), or not
// attempted (circuit breaker).
const failure = (j) => ({ ok: false, stage: j.stage, attempts: j.attempts ?? null, http_status: j.http_status ?? j.statusCode ?? null,
  class: j.decision === 'error' ? (j.retry_exhausted ? 'thehive_unreachable' : (j.http_status ? 'thehive_4xx' : 'thehive_error'))
    : (j.statusCode >= 400 && j.statusCode < 500 ? 'thehive_4xx' : `http_${j.statusCode}`),
  message: j.message ?? `HTTP ${j.statusCode}: ${JSON.stringify(j.body)}`.slice(0, 500) });
const j = $input.first().json;
const t = { ...j.t };
if (j.next === 'skip') t.patch = { ok: false, skipped: true };
else if (j.next === 'no_patch') t.patch = { ok: true, changed: false };
else if (j.decision === 'response' && j.statusCode >= 200 && j.statusCode < 300) t.patch = { ok: true, changed: true, attempts: j.attempts };
else {
  t.patch = failure(j);
  if (j.retry_exhausted === true) t.unreachable = true;
}
return [{ json: { t } }];

// C11 (N8N-2.9): a related alert's asox-metrics severity follows its TheHive
// severity (mode update: a missing document is skipped, never created). n8n's
// own TheHive writes are dropped by C4's loop prevention, so recv-thehive-event
// never sees this raise: the playbook writes it. `t` rides along (ignored by
// the lib) for "Metrics done".
const t = $input.first().json.t;
return [{ json: { ...t.metrics, config: $('Context').first().json.config, _t: t } }];

// lib-metrics-upsert never parks; On Error = continue, so an unexpected
// failure arrives as {error}. "Metrics input" runs once per call, like this node.
const r = $input.first().json;
const t = { ...$('Metrics input').all(0, $runIndex)[0].json._t };
t.metrics_result = { ok: r.ok === true, line: typeof r.line === 'string' ? r.line : 'metrics: failed (unexpected)' };
return [{ json: { t } }];

// Comment listing before each post (as lib-thehive-writeback does): the first
// listing, a retry of the listing, or the re-listing after a failed post (a
// post that timed out may have been written). post_attempt rides along.
const j = $input.first().json;
return [{ json: { t: j.t, list_attempt: j.retry_of === 'List TheHive comments' ? j.list_attempt + 1 : 1,
  post_attempt: j.post_attempt ?? 0 } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. The attempt
// number comes with the call ("Call: List TheHive comments", same run index: one run per call),
// not from $runIndex. Never parks: the last failure goes into the writeback.
const r = $input.first().json;
const call = $('Call: List TheHive comments').all(0, $runIndex)[0].json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'List TheHive comments';
const attempt = call.list_attempt;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { ...call, decision: 'retry', retry_of: NODE, stage: NODE, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { ...call, decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...call, decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// The escalation comment is written once per alert and escalating 40112:
// first line exactly `<marker> wazuh-alert-id=<40112 id>` by n8n's account
// (the same test as the writeback's). Otherwise write it, with what was done
// to this alert.
const j = $input.first().json;
const t = j.t;
const c = $('Context').first().json;
const sc = c.config.ssh_correlation;
const author = c.config.writeback.author;
const firstLine = `${sc.comment_marker} wazuh-alert-id=${t.escalation.marker_alert_id}`;
if (j.decision !== 'response' || j.statusCode !== 200 || !Array.isArray(j.body)) {
  const cls = j.decision === 'error' ? (j.retry_exhausted ? 'thehive_unreachable' : (j.http_status ? 'thehive_4xx' : 'thehive_error'))
    : (j.statusCode >= 400 && j.statusCode < 500 ? 'thehive_4xx' : (j.statusCode === 200 ? 'bad_answer' : `http_${j.statusCode}`));
  return [{ json: { t: { ...t, ...(j.retry_exhausted === true ? { unreachable: true } : {}),
    comment: { ok: false, stage: j.stage, class: cls, attempts: j.attempts ?? null, message: (j.message ?? `HTTP ${j.statusCode}`).slice(0, 500) } },
    status: 'done' } }];
}
const existing = j.body.find((cm) => (cm.createdBy ?? cm._createdBy) === author
  && typeof cm.message === 'string' && cm.message.split('\n')[0] === firstLine);
if (existing) return [{ json: { t: { ...t, comment: { ok: true, written: false, comment_id: existing._id } }, status: 'done' } }];
const iso = (ms) => (Number.isFinite(ms) ? new Date(ms).toISOString() : 'unknown time');
const e = t.escalation;
const sev = t.severity_to !== null
  ? `Severity raised ${t.severity_from} → ${t.severity_to} (lib-config ssh_correlation.escalate_severity); never lowered (D12).`
  : `Severity unchanged (${t.severity_from ?? 'unknown'}: already at or above ${sc.escalate_severity}).`;
const tagLine = t.add_tags.includes(sc.tags.escalated) ? `Tagged ${sc.tags.escalated}.` : `Already tagged ${sc.tags.escalated}.`;
const metricsLine = t.role === 'self'
  ? `asox-metrics: severity ${t.severity_final} written with this alert's document (its writeback).`
  : (t.metrics_result ? `asox-metrics severity ${t.severity_final}: ${t.metrics_result.line}` : 'asox-metrics: not updated.');
const lines = [
  firstLine,
  '',
  `n8n playbook **${c.context.playbook}**, execution ${c.context.n8n_execution_id}.`,
  '',
  `Successful SSH login after brute force from ${t.srcip}: Wazuh rule ${e.by_rule_id}, alert ${e.marker_alert_id} (TheHive ${e.by_thehive_alert_id}) at ${iso(e.by_date_ms)}.`,
  '',
  'Actions taken on this alert:',
  `- ${tagLine}`,
  `- ${sev}`,
  `- ${metricsLine}`,
  `- Recommended: block ${t.srcip} (response actions, C9 v0: the SSH playbook proposes a firewall-drop in its writeback, which an analyst approves with the tag approve:firewall-drop); nothing was changed.`,
];
return [{ json: { t, status: 'write', message: lines.join('\n'), post_attempt: j.post_attempt } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. The attempt
// number comes with the call ("Call: Post TheHive comment", same run index: one run per call),
// not from $runIndex. Never parks: the last failure goes into the writeback.
const r = $input.first().json;
const call = $('Call: Post TheHive comment').all(0, $runIndex)[0].json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Post TheHive comment';
const attempt = call.post_attempt;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { ...call, decision: 'retry', retry_of: NODE, stage: NODE, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { ...call, decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...call, decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// One alert done: reached from "Comment?" (no comment to write), from the
// comment check (already there, or the listing failed) or from the post.
const j = $input.first().json;
const t = { ...j.t };
if (j.stage === 'Post TheHive comment') {
  if (j.decision === 'response' && j.statusCode === 201) t.comment = { ok: true, written: true, comment_id: j.body?._id ?? null, attempts: j.attempts };
  else {
    t.comment = { ok: false, stage: j.stage, attempts: j.attempts ?? null, http_status: j.http_status ?? j.statusCode ?? null,
      class: j.decision === 'error' ? (j.retry_exhausted ? 'thehive_unreachable' : (j.http_status ? 'thehive_4xx' : 'thehive_error'))
        : (j.statusCode >= 400 && j.statusCode < 500 ? 'thehive_4xx' : `http_${j.statusCode}`),
      message: (j.message ?? `HTTP ${j.statusCode}: ${JSON.stringify(j.body)}`).slice(0, 500) };
    if (j.retry_exhausted === true) t.unreachable = true;
  }
}
return [{ json: { kind: 'escalation_target', t } }];

// Reached by exactly one path: nothing to write, or the loop done (one
// `escalation_target` item per TheHive alert).
const targets = $input.all().map((x) => x.json).filter((j) => j.kind === 'escalation_target').map((j) => j.t);
return [{ json: {
  ran: targets.length > 0,
  self: targets.find((t) => t.role === 'self') ?? null,
  related: targets.filter((t) => t.role === 'related'),
} }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. Outside the
// loop: this node runs once per call, so $runIndex counts the attempts.
// Never parks: the last failure goes into the result.
const r = $input.first().json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Re-read TheHive alert';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// N8N-4.2 follow-up: this alert's asox-metrics document was just created (or
// repaired) with the severity this run knew. A 40112 in the other queue slot
// may have raised the TheHive alert meanwhile, and its metrics update then
// found no document (skipped). Re-read the severity now that the document
// exists: a raise before this read is seen here, a raise after it finds the
// document. Follows TheHive both ways (an analyst may lower it, C4). Never
// parks: a failure is only reported in the result (`metrics_resync`).
const j = $input.first().json;
const m = $('Writeback input').first().json.metrics;
const written = m.fields.severity;
const fail = (why) => ({ status: 'failed', from: written, line: `metrics: severity re-sync failed (re-read: ${why})` });
const calls = j.attempts ? ` after ${j.attempts} call(s)` : '';
let out;
if (j.decision === 'error') {
  out = fail(`${j.retry_exhausted ? 'thehive_unreachable' : 'thehive_error'}${calls}`);
} else if (j.statusCode !== 200) {
  out = fail(`${j.statusCode >= 400 && j.statusCode < 500 ? 'thehive_4xx' : 'http'} ${j.statusCode}`);
} else if (!Array.isArray(j.body) || j.body.length !== 1 || !Number.isInteger(j.body[0]?.severity)) {
  out = fail('unexpected answer');
} else {
  const now = j.body[0].severity;
  out = now === written
    ? { status: 'unchanged', from: written, to: now }
    : { status: 'update', from: written, to: now,
      metrics: { mode: 'update', alert_id: m.alert_id, source: m.source, fields: { severity: now } } };
}
return [{ json: out }];

// lib-metrics-upsert, mode update, `severity` only (its overwrite rule is
// unchanged: the latest value wins).
return [{ json: { ...$input.first().json.metrics, config: $('Context').first().json.config } }];

// C9 v0: a response proposal for this alert's source address (nothing is
// sent: lib-wazuh-active-response, action propose, runs the same guardrails
// and agent lookups as an execution). Only when lib-config response is
// enabled, the route is in response.routes and the alert has a data.srcip;
// otherwise the reason goes into the writeback's "Recommended" line.
const c = $('Context').first().json;
const b = $('Alert base (lib-alert-base)').first().json;
const resp = c.config.response;
const routeId = c.route?.route_id ?? null;
const srcip = typeof b.canonical?.network?.srcip === 'string' && b.canonical.network.srcip.trim() !== '' ? b.canonical.network.srcip.trim() : null;
let skip = null;
if (!resp || resp.enabled !== true) skip = 'response actions disabled (lib-config response.enabled)';
else if (!resp.routes.includes(routeId)) skip = `route ${routeId ?? 'none'} is not in lib-config response.routes`;
else if (!srcip) skip = 'no data.srcip';
if (skip) return [{ json: { propose: false, reason: skip, srcip } }];
return [{ json: { propose: true, action: 'propose', command: 'firewall-drop', srcip,
  agent: { name: b.canonical.agent.name }, config: c.config, context: c.context } }];
